const p = require\("path"\);
const fp = p.join\("C:", "Code", "vaani", "server.ts"\);
let c = fs.readFileSync\(fp, "utf8"\);

const replacements = [
  [["console.log\(`[relay] Setting translation source for ${userId} to ${msg.source}`\);", "logger.info\({ userId, source: msg.source }, \\"Translation source set\\"\);"]],
  [["console.log\(`[relay] Hot-reloading audio extraction for user ${userId}`\);", "logger.info\({ userId }, \\"Audio extraction hot-reload\\"\);"]],
  [["console.log\(`[relay] Setting TTS settings for user ${userId}: speaker=${msg.speaker}, pace=${msg.pace}, sourceLang=${msg.sourceLang}`\);", "logger.debug\({ userId, speaker: msg.speaker, pace: msg.pace, sourceLang: msg.sourceLang }, \\"TTS settings set\\"\);"]],
  [["console.log\(`[relay] WS closed for user ${userId}`\);", "logger.info\({ userId }, \\"WS closed\\"\);"]],
  [["console.error\(`[relay] WS error for user ${userId}:`, err\);", "logger.error\({ err, userId }, \\"WS error\\"\);"]],
  [["console.log\(`> Ready on http://${hostname}:${port}`\);", "logger.info\({ hostname, port }, \\"Server ready\\"\);"]],
  [["console.log\(\\"\\\\n[server] Shutting down gracefully...\\"\);", "logger.info\(\\"Graceful shutdown initiated\\"\);"]],
  [["console.log\(`[server] Stopping RTMP streamer for user ${userId}`\);", "logger.info\({ userId }, \\"Stopping RTMP streamer\\"\);"]],
  [["console.log\(`[server] Stopping audio extractor for user ${userId}`\);", "logger.info\({ userId }, \\"Stopping audio extractor\\"\);"]],
  [["console.log\(\\"[server] Stopping Node Media Server...\\"\);", "logger.info\(\\"Stopping NMS\\"\);"]],
  [["console.log\(\\"[server] HTTP and WS servers closed.\\"\);", "logger.info\(\\"Servers closed\\"\);"]],
  [["console.error\(\\"[server] Forced shutdown after 10s\\"\);", "logger.error\(\\"Forced shutdown after timeout\\"\);"]],
  [["console.error\(`[relay] RTMP error for user ${userId}:`, err.message\);", "logger.error\({ err: err.message, userId }, \\"RTMP streamer error\\"\);"]],
  [["console.log\(`[relay] RTMP stopped for user ${userId}`\);", "logger.info\({ userId }, \\"RTMP stopped\\"\);"]],
  [["console.log\(`[relay] RTMP streamer started for user ${userId} with ${rtmpConfigs.length} destination\(s\)`\);", "logger.info\({ userId, destinations: rtmpConfigs.length }, \\"RTMP streamer started\\"\);"]],
  [["console.warn\(`[relay] RTMP streamer failed to start for user ${userId}`\);", "logger.warn\({ userId }, \\"RTMP streamer failed to start\\"\);"]],
  [["console.log\(`[relay] No RTMP destinations configured — pipeline-only mode`\);", "logger.info\({ userId }, \\"Pipeline-only mode\\"\);"]],
  [["console.log\(`[relay] Session started for user ${userId} with languages: ${languages.join\(\\", \\"\)}`\);", "logger.info\({ userId, languages: languages.join\(\\", \\"\) }, \\"Session started\\"\);"]],
  [["console.error\(`[relay] GO_LIVE failed for user ${userId}:`, err\);", "logger.error\({ err, userId }, \\"GO_LIVE failed\\"\);"]],
];

for \(const [before, after] of replacements\) {
  if \(c.includes\(before\)\) {
    c = c.replace\(before, after\);
    console.log\("replaced:", before.slice\(0, 60\) + "..."\);
  } else {
    console.log\("NOT FOUND:", before.slice\(0, 60\) + "..."\);
  }
}

fs.writeFileSync\(fp, c\);
console.log\("Done. Remaining console.* calls:", \(c.match\(/console\\./g\) || []\).length\);
